writecsv('london_blackfriars_calculations.csv',[{'metric':'combined carriageway and cycle track throughput','value':3480,'unit':'people/hour','formula':'1542+1938','limitations':'excludes footways and rail; snapshot only'}, {'metric':'cycle share of these two facilities','value':1938/3480*100,'unit':'percent','formula':'1938/(1542+1938)*100','limitations':'not all-mode share; no baseline'}, {'metric':'cycle track/main carriageway people ratio','value':1938/1542,'unit':'ratio','formula':'1938/1542','limitations':'5x cited by TfL normalizes road space, not actual throughput ratio'}])
