# Tidy original Manchester table data and independently reproduce percentages.
bust=[]
for table in ['4_6','4_9','4_8','4_10']:
 rows=list(csv.reader((p/f'manchester_table_{table}.csv').open()))
 for row in rows[1:]:
  # grid-merged rows contain blank first cell, preserving time period in next cell
  if len(row)>=5 and re.fullmatch(r'\d\d:\d\d:\d\d',row[2]):
   seconds=lambda x:sum(int(v)*k for v,k in zip(x.split(':'),[3600,60,1]))
   b,a=seconds(row[2]),seconds(row[3]);reported=float(row[4].replace('%','').replace('+',''))
   bust.append({'table':table.replace('_','.'),'direction':'MRI to city' if table in ['4_6','4_8'] else 'city to MRI','measure':'local observed bus time' if table in ['4_6','4_9'] else 'constructed through-trip time incl interchange allowance','time_period':row[1],'before_year':2013,'after_year':2018,'before_seconds':b,'after_seconds':a,'change_seconds':a-b,'calculated_change_percent':(a/b-1)*100,'reported_change_percent':reported,'percent_mismatch_over_1pt':abs((a/b-1)*100-reported)>1,'source':man})
writecsv('manchester_bus_time_calculations.csv',bust)
rt=list(csv.reader((p/'manchester_table_5_13.csv').open()));derived=[]
for i in range(1,len(rt),4):
 period=rt[i][0]
 for j,year in enumerate([2013,2018,2019,2022,2023],1):
  a,b=float(rt[i+1][j]),float(rt[i+2][j]);derived.append({'period':period,'year':year,'upper_brook_index_2013_100':a,'radial_comparator_index_2013_100':b,'relative_percent_change':(a/b-1)*100,'index_difference_points':a-b,'source_table':'5.13','warning':'Single pre period, no uncertainty; Upper Brook received capacity expansion; pooled four radials, possible spillovers; no causal bike-only estimate'})
writecsv('manchester_parallel_road_calculations.csv',derived)
# Join AADF values with quality flags.
aadf=[]
for f in p.glob('dft_aadf_*.json'):aadf+=json.loads(f.read_text())['data']
writecsv('london_dft_aadf_with_quality.csv',aadf)
