 {'city':'London','project':'Lancaster Gate CS3 extension','priority':'Excluded: insufficient after-data','treatment':'Cycle Superhighway scheme; exact moving-lane loss not validated','timing':'Motorbaseline2013; cycle2014vs2018','observations':[{'metric':'bidirectionalcycles06:00-22:00','before':3163,'after':3227,'source':'FOI-0661-1920'}],'causal_design':'No suitable design available','limitations':['TfLFOI says did not collect post-scheme motor counts asstandard practice','No speed data collected','Does not improve causalall-modeoutcome coverage'],'urls':['https://tfl.gov.uk/corporate/transparency/freedom-of-information/foi-request-detail?referenceId=FOI-0661-1920'],'files':[]}
