(p/'candidates.json').write_text(json.dumps(candidates,indent=2))
# All source downloads preserved, with hashes for audit.
manifest=[]
for f in sorted(p.glob('*')):
 if f.is_file() and f.suffix in ['.json','.csv','.pdf','.docx','.txt']:
  manifest.append({'file':f.name,'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
(p/'manifest.json').write_text(json.dumps(manifest,indent=2))
print('Wrote',len(candidates),'candidates and',len(manifest),'source/data files')
print('Bus arithmetic discrepancy:',[r for r in bust if r['percent_mismatch_over_1pt']])
